SELECT 

WHERE 1 = 1

AND c.comment_time >= #{query.commentTimeFrom}
AND c.comment_time <= #{query.commentTimeTo}
AND c.shop_id = #{query.shopId}

    AND (s.name LIKE CONCAT('%', #{query.shopKeyword}, '%') OR s.poi_name LIKE CONCAT('%', #{query.shopKeyword}, '%') OR s.epoi_id LIKE CONCAT('%', #{query.shopKeyword}, '%'))

AND c.comment_id = #{query.commentId}

    AND (c.comment_content LIKE CONCAT('%', #{query.keyword}, '%') OR c.add_comment LIKE CONCAT('%', #{query.keyword}, '%'))

AND  = #{query.sentiment}
AND c.auto_reply_status = #{query.autoReplyStatus}

    AND CASE WHEN  != 'BAD' THEN 'NOT_APPLICABLE'
             WHEN cp.id IS NULL AND c.complaint_status = 'PENDING' THEN 'NOT_TRIGGERED'
             ELSE COALESCE(cp.status, c.complaint_status) END = #{query.complaintStatus}


    AND CASE WHEN  != 'BAD' THEN 'NOT_APPLICABLE'
             WHEN im.id IS NULL AND c.im_follow_up_status = 'PENDING' THEN 'NOT_TRIGGERED'
             ELSE COALESCE(im.status, c.im_follow_up_status) END = #{query.imFollowUpStatus}

ORDER BY c.comment_time DESC, c.create_time DESC, c.id DESC
